def repr_runtime_for_host(source):
    """Use this compiler's Python printability table for a self-contained v2 runtime."""
    if sys.implementation.name == 'cpython' and sys.version_info[:3] == (3, 13, 6):
        return source
    marker = 'static const uint32_t ail_repr_unprintable[][2] = {\n'
    before, remainder = source.split(marker, 1)
    _, after = remainder.split('};', 1)
    ranges = []
    start = end = None
    for codepoint in range(128, 0x110000):
        if not chr(codepoint).isprintable():
            if start is None:
                start = codepoint
            elif codepoint != end + 1:
                ranges.append((start, end))
                start = codepoint
            end = codepoint
    if start is not None:
        ranges.append((start, end))
    table = ''.join(f'    {{{low}, {high}}},\n' for low, high in ranges)
    return before + marker + table + '};' + after

