def _pop_edit(p, text):
    for old, new in POP_EDITS[p]:
        if text.count(old) != 1:
            raise AssertionError('%s changed; update cruntime.POP_EDITS' % p)
        text = text.replace(old, new)
    return text


def _piece(p, want):
    text = _piece_text(p, want)
    if p in ('TYPES', 'TAB') and 'SETOPS' in want or p in ('STAB', 'SDICT') and 'SSETOPS' in want:
        text = _pop_edit(p, text)
    return text


def _piece_text(p, want):
    text = (_overflow_exception(_assert_exception(SOURCE[p])) if p == 'DIE' and 'OVERFLOWEXC' in want
            else _assert_exception(SOURCE[p]) if p == 'DIE' and 'ASSERTEXC' in want else SOURCE[p])
    if p == 'DIE' and 'OSEXC' in want:
        text = _os_exception(text)
        if 'EXCSTR' in want:
            text = _exctext.apply(text, _exctext.DIE_EDITS, 'the DIE block')
            text = text.replace('!strcmp(w, "integer overflow")', '!strcmp(w, "integer overflow") || !strcmp(w, "cannot convert float infinity to integer")')
    if p == 'OSEXC' and 'EXCSTR' in want:
        text = _exctext.apply(text, _exctext.OSEXC_EDITS, 'the OSEXC part')
    if p == 'DIE' and 'FILEEXC' in want:
        text = _filert.file_exception(text, 'FILECORE' in want)
        if 'PROCEXC' in want:
            text = _filert.proc_exception(text)
        if 'SQLEXC' in want:
            text = _filert.sql_exception(text)         # G11: sqlite3 exception codes 19..27
        if 'HTTPEXC' in want:
            text = _filert.http_exception(text)        # G12: URLError / HTTPError, codes 30, 31 (after the others)
    elif p in _filert.LEGACY_EDITS and 'FILEEXC' in want:
        text = _filert.legacy_errno(p, text)
    if p == 'DIE' and 'EXCCLASSES' in want:
        text = _exctext.classes_table(text)          # S4e: Exception (28) and the user exception classes (29..)
    if 'EXCSTR' in want and p != 'DIE':
        text = _exctext.part_edit(p, text)
    if p == 'IREXC':
        return text.replace('/*IRPAR*/', 'if (ail_par_cur) ail_par_trap(NULL, code);' if 'PAR' in want else '')
    if p == 'PAR' and 'PARN' in want:
        text = _par_capped(text)
        if 'EXCSTR' in want:
            # a worker's ail_raise_msg (CPython's wording of a trap) is recorded with its code and raised again
            # with both on the calling thread
            text = _exctext.apply(text, (('        if (msg[0]) ail_die(msg);\n',
                                          '        if (msg[0] && code) ail_raise_msg(code, msg);\n'
                                          '        if (msg[0]) ail_die(msg);\n'),), 'the PARN part')
    if p == 'DIE' and 'PARN' in want and 'EXCSTR' in want:
        text = _exctext.apply(text, (('static void ail_raise_msg(int code, const char *t) {\n',
                                      'static void ail_raise_msg(int code, const char *t) {\n'
                                      '    if (ail_par_cur) ail_par_trap(t, code);\n'),), 'the DIE block (PARN)')
    return _parallel_die(text) if p == 'DIE' and 'PAR' in want else text


# A `parallel for` body runs on worker threads, where a trap (ail_die, ail_raise_named) must not
# longjmp across threads or touch the exception stack. With PAR in the program, the two entry points
# check a thread-local first: a worker's trap is recorded and the worker unwinds to its own block
# runner (PAR below); the caller re-raises it after the join. Programs without PAR keep the DIE
# block byte for byte.
_PARALLEL_DIE_EDITS = (
    ('static void ail_die(const char *w);\n',
     'AIL_LINK_STATE(_Thread_local void *, ail_par_cur, = NULL);\n'
     'static void ail_par_trap(const char *w, int code) __attribute__((noreturn));\n'
     'static void ail_die(const char *w);\n'),
    ('static void ail_die(const char *w) {\n', 'static void ail_die(const char *w) {\n    if (ail_par_cur) ail_par_trap(w, 0);\n'),
    ('static void ail_raise_named(int code) {\n', 'static void ail_raise_named(int code) {\n    if (ail_par_cur) ail_par_trap(NULL, code);\n'),
)


def _parallel_die(text):
    for old, new in _PARALLEL_DIE_EDITS:
        if text.count(old) != 1:
            raise AssertionError('DIE block changed; update _PARALLEL_DIE_EDITS: ' + old)
        text = text.replace(old, new)
    return text


# AssertionError is exception code 9. Programs that never name it keep the DIE block byte for
# byte (the codegen pins hash it), so the extra code is spliced in only when the ASSERTEXC part
# is requested: by an `assert` statement or any `raise`/`except`/constructor of AssertionError.
_ASSERT_EXCEPTION_EDITS = (
    ('AIL_EXC_UNICODE_DECODE = 8 };', 'AIL_EXC_UNICODE_DECODE = 8, AIL_EXC_ASSERTION = 9 };'),
    ('"RuntimeError", "UnicodeDecodeError"};', '"RuntimeError", "UnicodeDecodeError", "AssertionError"};'),
    ('return code >= 1 && code <= 8 ? names[code]', 'return code >= 1 && code <= 9 ? names[code]'),
    ('if (code < 1 || code > 8 || n < 0', 'if (code < 1 || code > 9 || n < 0'),
    ('if (code < 1 || code > 8) code = AIL_EXC_RUNTIME;', 'if (code < 1 || code > 9) code = AIL_EXC_RUNTIME;'),
)


# OverflowError is exception code 10, spliced on top of the AssertionError edits the same way:
# only a program that names OverflowError gets it, and there "integer overflow" (int64 arithmetic
# leaving the range) becomes catchable instead of ending the program.
_OVERFLOW_EXCEPTION_EDITS = (
    ('AIL_EXC_ASSERTION = 9 };', 'AIL_EXC_ASSERTION = 9, AIL_EXC_OVERFLOW = 10 };'),
    ('"AssertionError"};', '"AssertionError", "OverflowError"};'),
    ('return code >= 1 && code <= 9 ? names[code]', 'return code >= 1 && code <= 10 ? names[code]'),
    ('if (code < 1 || code > 9 || n < 0', 'if (code < 1 || code > 10 || n < 0'),
    ('if (code < 1 || code > 9) code = AIL_EXC_RUNTIME;', 'if (code < 1 || code > 10) code = AIL_EXC_RUNTIME;'),
    ('    if (!strcmp(w, "key error")) return AIL_EXC_KEY;\n',
     '    if (!strcmp(w, "key error")) return AIL_EXC_KEY;\n'
     '    if (!strcmp(w, "integer overflow") || !strcmp(w, "(34, \'Numerical result out of range\')")) return AIL_EXC_OVERFLOW;\n'),
)


def _overflow_exception(text):
    for old, new in _OVERFLOW_EXCEPTION_EDITS:
        if text.count(old) != 1:
            raise AssertionError('DIE block changed; update _OVERFLOW_EXCEPTION_EDITS: ' + old)
        text = text.replace(old, new)
    return text


def _assert_exception(text):
    for old, new in _ASSERT_EXCEPTION_EDITS:
        if text.count(old) != 1:
            raise AssertionError('DIE block changed; update _ASSERT_EXCEPTION_EDITS: ' + old)
        text = text.replace(old, new)
    return text


HEXINT = r"""
/* hex(n), bin(n), oct(n): [-]0x.. / 0b.. / 0o.. of the magnitude (|INT64_MIN| fits a uint64) */
static ail_str ail_int_radix(ail_sarena *A, int64_t value, int shift, char prefix) {
    static const char digits[] = "0123456789abcdef";
    uint64_t magnitude = (uint64_t)value;
    if (value < 0) magnitude = UINT64_C(0) - magnitude;
    uint16_t reversed[64];
    int64_t count = 0;
    do {
        reversed[count++] = (uint16_t)digits[magnitude & ((UINT64_C(1) << shift) - 1)];
        magnitude >>= shift;
    } while (magnitude);
    int64_t length = count + 2 + (value < 0);
    uint8_t *out = ail_sarena_alloc(A, length);
    int64_t position = 0;
    if (value < 0) out[position++] = '-';
    out[position++] = '0'; out[position++] = (uint8_t)prefix;
    while (count) out[position++] = reversed[--count];
    return (ail_str){out, length, 0};
}
static ail_str ail_int_hex(ail_sarena *A, int64_t value) { return ail_int_radix(A, value, 4, 'x'); }
static ail_str ail_int_bin(ail_sarena *A, int64_t value) { return ail_int_radix(A, value, 1, 'b'); }
static ail_str ail_int_oct(ail_sarena *A, int64_t value) { return ail_int_radix(A, value, 3, 'o'); }
"""
ORDER.append('HEXINT')
SOURCE['HEXINT'] = HEXINT
REQUIRES['HEXINT'] = ['STR']

