# ---- KEYSORT: decorate-sort-undecorate for sorted(key=...) / list.sort(key=...) -----------------
#
# The compiler evaluates each key expression ONCE per element, into a column (an int64, double or
# str list the program could have written itself), then hands the columns here. `ail_keysort_perm`
# fills `out` with the permutation that orders the elements by (column 0, column 1, ...) -- a
# STABLE bottom-up merge sort over the index array, so equal keys keep their input order exactly
# like CPython's list.sort, and `reverse=True` keeps equal elements in INPUT order too (CPython
# reverses, stable-sorts, reverses back; a stable sort under the opposite comparison is the same
# thing). `ail_perm_apply` then moves the elements themselves, once.
KEYSORTSTR = r"""
#define AIL_KEYSORT_STR 1
"""
KEYSORT = r"""
#include <math.h>
/* kind 0 int64_t, 1 double, 2 ail_str; `pre` (filled by ail_keysort_perm for a str column) holds
   each string's first eight bytes, big-endian, so most comparisons never touch the text. */
typedef struct { int kind; const void *p; int64_t n; const uint64_t *pre; } ail_keycol;
#define AIL_KEYSORT_MAX 16
static inline int ail_keycol_cmp(const ail_keycol *c, int nc, int64_t a, int64_t b) {
    for (int k = 0; k < nc; k++) {
        int r;
        if (c[k].kind == 0) {
            const int64_t *p = (const int64_t *)c[k].p;
            r = (p[a] > p[b]) - (p[a] < p[b]);
        } else if (c[k].kind == 1) {
            const double *p = (const double *)c[k].p;
            r = (p[a] > p[b]) - (p[a] < p[b]);
        } else {
#ifdef AIL_KEYSORT_STR
            const ail_str *p = (const ail_str *)c[k].p;
            uint64_t x = c[k].pre[a], y = c[k].pre[b];
            r = x != y ? (x < y ? -1 : 1) : (int)ail_str_cmp(p[a], p[b]);
#else
            r = 0;
#endif
        }
        if (r) return r;
    }
    return 0;
}
/* true when element b must come before element a (strictly), under the requested direction */
static inline int ail_keysort_before(const ail_keycol *c, int nc, int rev, int64_t b, int64_t a) {
    int r = ail_keycol_cmp(c, nc, b, a);
    return rev ? r > 0 : r < 0;
}
/* One int64 key column -- `order.sort(key=lambda i: arr[i])`, the commonest keyed sort -- with the
   comparison written out: the same stable bottom-up merge sort as below, without the per-compare
   walk over columns and kinds (28% of an LLM-written berth scheduler sorting 3M indices twice).
   BEFORE(b, a) is true when b must come strictly before a. */
#define AIL_KEYSORT_I64(NAME, BEFORE) \
static void NAME(int64_t *perm, int64_t *buf, int64_t n, const int64_t *key, int rev) { \
    int64_t *src = perm, *dst = buf; \
    const int64_t RUN = 8; \
    for (int64_t lo = 0; lo < n; lo += RUN) { \
        int64_t hi = lo + RUN < n ? lo + RUN : n; \
        for (int64_t i = lo + 1; i < hi; i++) { \
            int64_t v = src[i], kv = key[v], j = i; \
            while (j > lo && BEFORE(kv, key[src[j - 1]])) { src[j] = src[j - 1]; j--; } \
            src[j] = v; \
        } \
    } \
    for (int64_t width = RUN; width < n; width *= 2) { \
        for (int64_t lo = 0; lo < n; lo += 2 * width) { \
            int64_t mid = lo + width < n ? lo + width : n; \
            int64_t hi = lo + 2 * width < n ? lo + 2 * width : n; \
            int64_t i = lo, j = mid, o = lo; \
            if (mid >= hi || !BEFORE(key[src[mid]], key[src[mid - 1]])) { \
                memcpy(dst + lo, src + lo, (size_t)(hi - lo) * sizeof *src); \
                continue; \
            } \
            while (i < mid && j < hi) \
                dst[o++] = BEFORE(key[src[j]], key[src[i]]) ? src[j++] : src[i++]; \
            while (i < mid) dst[o++] = src[i++]; \
            while (j < hi) dst[o++] = src[j++]; \
        } \
        int64_t *swap = src; src = dst; dst = swap; \
    } \
    if (src != perm) memcpy(perm, src, (size_t)n * sizeof *src); \
}
/* The general form over (column, kind) lists, and one whose first column is int64 -- `(-count[i],
   name[i])` -- compared inline, the rest only on a tie. */
#define AIL_KEYSORT_COLS(NAME, BEFORE) \
static void NAME(int64_t *perm, int64_t *buf, int64_t n, const ail_keycol *cols, int nc, int rev) { \
    int64_t *src = perm, *dst = buf; \
    const int64_t RUN = 8; \
    for (int64_t lo = 0; lo < n; lo += RUN) { \
        int64_t hi = lo + RUN < n ? lo + RUN : n; \
        for (int64_t i = lo + 1; i < hi; i++) { \
            int64_t v = src[i], j = i; \
            while (j > lo && BEFORE(v, src[j - 1])) { src[j] = src[j - 1]; j--; } \
            src[j] = v; \
        } \
    } \
    for (int64_t width = RUN; width < n; width *= 2) { \
        for (int64_t lo = 0; lo < n; lo += 2 * width) { \
            int64_t mid = lo + width < n ? lo + width : n; \
            int64_t hi = lo + 2 * width < n ? lo + 2 * width : n; \
            int64_t i = lo, j = mid, o = lo; \
            if (mid >= hi || !BEFORE(src[mid], src[mid - 1])) { \
                memcpy(dst + lo, src + lo, (size_t)(hi - lo) * sizeof *src); \
                continue; \
            } \
            while (i < mid && j < hi) \
                dst[o++] = BEFORE(src[j], src[i]) ? src[j++] : src[i++]; \
            while (i < mid) dst[o++] = src[i++]; \
            while (j < hi) dst[o++] = src[j++]; \
        } \
        int64_t *swap = src; src = dst; dst = swap; \
    } \
    if (src != perm) memcpy(perm, src, (size_t)n * sizeof *src); \
}
#define AIL_KEY_ANY(b, a) ail_keysort_before(cols, nc, rev, (b), (a))
static inline int ail__key_i64_first(const ail_keycol *cols, int nc, int rev, int64_t b, int64_t a) {
    const int64_t *k = (const int64_t *)cols[0].p;
    if (k[b] != k[a]) return rev ? k[b] > k[a] : k[b] < k[a];
    return ail_keysort_before(cols + 1, nc - 1, rev, b, a);
}
#define AIL_KEY_I64_FIRST(b, a) ail__key_i64_first(cols, nc, rev, (b), (a))
AIL_KEYSORT_COLS(ail__keysort_any, AIL_KEY_ANY)
AIL_KEYSORT_COLS(ail__keysort_i64_first, AIL_KEY_I64_FIRST)
#define AIL_KEY_I64(x, y) (rev ? (x) > (y) : (x) < (y))
AIL_KEYSORT_I64(ail__keysort_i64, AIL_KEY_I64)
static void ail_keysort_perm(ail_list *out, const ail_keycol *given, int nc, int rev) {
    if (nc > AIL_KEYSORT_MAX) ail_die("too many sort key components");
    ail_keycol cols[AIL_KEYSORT_MAX];
    uint64_t *owned[AIL_KEYSORT_MAX];
    int64_t n = nc ? given[0].n : 0;
    for (int k = 0; k < nc; k++) {
        cols[k] = given[k];
        owned[k] = 0;
        if (given[k].n != n) ail_die("sort keys of different lengths");
        if (given[k].kind == 1) {
            const double *d = (const double *)given[k].p;
            for (int64_t i = 0; i < n; i++) if (isnan(d[i])) ail_raise_named(AIL_EXC_VALUE);
        }
#ifdef AIL_KEYSORT_STR
        if (given[k].kind == 2) {
            const ail_str *s = (const ail_str *)given[k].p;
            uint64_t *pre = (uint64_t *)malloc((size_t)(n > 0 ? n : 1) * sizeof *pre);
            if (!pre) ail_die("out of memory");
            for (int64_t i = 0; i < n; i++) {
                uint64_t v = 0;
                int64_t m = s[i].n < 8 ? s[i].n : 8;
                for (int64_t j = 0; j < m; j++) v |= (uint64_t)s[i].p[j] << (56 - 8 * j);
                pre[i] = v;
            }
            owned[k] = pre;
            cols[k].pre = pre;
        }
#endif
    }
    out->n = 0;
    if (n > 0) {
        if (out->cap < n) {
            if ((uint64_t)n > SIZE_MAX / sizeof *out->p) ail_die("list too long");
            int64_t *q = (int64_t *)realloc(out->p, (size_t)n * sizeof *q);
            if (!q) ail_die("out of memory");
            out->p = q; out->cap = n;
        }
        for (int64_t i = 0; i < n; i++) out->p[i] = i;
        out->n = n;
    }
    if (n >= 2 && nc == 1 && cols[0].kind == 0) {
        int64_t *buf = (int64_t *)malloc((size_t)n * sizeof *buf);
        if (!buf) ail_die("out of memory");
        ail__keysort_i64(out->p, buf, n, (const int64_t *)cols[0].p, rev);
        free(buf);
    } else if (n >= 2) {
        int64_t *buf = (int64_t *)malloc((size_t)n * sizeof *buf);
        if (!buf) ail_die("out of memory");
        if (cols[0].kind == 0) ail__keysort_i64_first(out->p, buf, n, cols, nc, rev);
        else ail__keysort_any(out->p, buf, n, cols, nc, rev);
        free(buf);
    }
    for (int k = 0; k < nc; k++) free(owned[k]);
}
/* v[i] = old v[perm[i]] for every i, once, through one scratch copy. */
static void ail_perm_apply(void *items, size_t size, int64_t n, const int64_t *perm, int64_t pn) {
    if (pn != n) ail_die("sort permutation does not match the list");
    if (n < 2) return;
    unsigned char *old = (unsigned char *)malloc((size_t)n * size);
    if (!old) ail_die("out of memory");
    unsigned char *v = (unsigned char *)items;
    memcpy(old, v, (size_t)n * size);
    for (int64_t i = 0; i < n; i++) memcpy(v + (size_t)i * size, old + (size_t)perm[i] * size, size);
    free(old);
}
"""
ORDER.append('KEYSORTSTR')
SOURCE['KEYSORTSTR'] = KEYSORTSTR
REQUIRES['KEYSORTSTR'] = ['SLIST']
ORDER.append('KEYSORT')
SOURCE['KEYSORT'] = KEYSORT
REQUIRES['KEYSORT'] = ['TYPES', 'DIE', 'LIST']


# `parallel for i in range(a, b) { ... }`: pyfunc._par_outline moves the loop body into a worker
# function `void w(void **args, int64_t lo, int64_t hi)` (args: addresses of the captured locals) and
# calls ail_par_run, which cuts [lo, hi) into blocks and deals them out to a pool of threads. The
# body touches no shared mutable runtime state (parallel.py's rules), so any schedule produces the
# sequential result. A trap in an iteration is recorded; after the join the trap of the LOWEST
# failing block is raised on the calling thread, which is the one a sequential run reaches first
# (blocks are claimed in order, and no block is claimed once one has failed, so every block before
# the failing one ran). A loop too small to pay for waking the pool runs on the calling thread:
# loops of more than 64 iterations are timed on their first iterations (ail_par_site remembers the
# verdict per call site), so a cheap loop costs no more than the plain loop plus a few clock reads.
PAR = r"""
#include <pthread.h>
#include <time.h>
#ifdef _WIN32
#include <windows.h>
#else
#include <unistd.h>
#endif
typedef void (*ail_par_fn)(void **, int64_t, int64_t);
typedef struct {
    ail_par_fn fn; void **args; int64_t lo, hi, block, nblocks, next, fail_block, abort;
    int fail_code; char fail_msg[192];
    pthread_mutex_t mu;
} ail_par_job;
typedef struct { jmp_buf jb; char msg[192]; int code; } ail_par_ctx;
typedef struct { int64_t light_n, heavy_n; } ail_par_site;   /* zeroed: nothing known yet */
/* Time spent on the calling thread before a long loop is sized up, and the least remaining work
   (at the rate seen so far) for which waking the pool is worth it. */
#define AIL_PAR_PROBE_NS 40000
#define AIL_PAR_MIN_NS 1000000
#define AIL_PAR_SPIN_NS 60000
#if defined(__x86_64__) || defined(__i386__)
#define AIL_PAR_RELAX() __builtin_ia32_pause()
#elif defined(__aarch64__)
#define AIL_PAR_RELAX() __asm__ __volatile__("yield")
#else
#define AIL_PAR_RELAX() ((void)0)
#endif
static void ail_par_trap(const char *w, int code) {
    ail_par_ctx *c = (ail_par_ctx *)ail_par_cur;
    c->code = code;
    c->msg[0] = 0;
    if (w) { strncpy(c->msg, w, sizeof c->msg - 1); c->msg[sizeof c->msg - 1] = 0; }
    longjmp(c->jb, 1);
}
static int64_t ail_par_now(void) {
#ifdef _WIN32
    LARGE_INTEGER f, t; QueryPerformanceFrequency(&f); QueryPerformanceCounter(&t);
    return (int64_t)((double)t.QuadPart * 1e9 / (double)f.QuadPart);
#else
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return (int64_t)t.tv_sec * 1000000000LL + t.tv_nsec;
#endif
}
static int ail_par_threads(void) {
    static int cached = 0;
    if (cached) return cached;
    int n = 0;
    const char *e = getenv("AIL_THREADS");
    if (e && *e) n = atoi(e);
    if (n <= 0) {
#ifdef _WIN32
        SYSTEM_INFO si; GetSystemInfo(&si); n = (int)si.dwNumberOfProcessors;
#else
        long c = sysconf(_SC_NPROCESSORS_ONLN); n = c > 0 ? (int)c : 1;
#endif
    }
    if (n < 1) n = 1;
    if (n > 256) n = 256;
    return cached = n;
}
/* One block; the setjmp lives here so no local of the caller is indeterminate after a trap. */
static __attribute__((noinline)) int ail_par_block(ail_par_ctx *c, ail_par_job *J, int64_t lo, int64_t hi) {
    if (setjmp(c->jb)) return 1;
    J->fn(J->args, lo, hi);
    return 0;
}
static void ail_par_work(ail_par_job *J) {
    ail_par_ctx c;
    ail_par_cur = &c;
    for (;;) {
        if (__atomic_load_n(&J->abort, __ATOMIC_RELAXED)) break;
        int64_t b = __atomic_fetch_add(&J->next, 1, __ATOMIC_RELAXED);
        if (b >= J->nblocks) break;
        int64_t lo = J->lo + b * J->block, hi = lo + J->block;
        if (hi > J->hi || hi < lo) hi = J->hi;
        if (ail_par_block(&c, J, lo, hi)) {
            pthread_mutex_lock(&J->mu);
            if (b < J->fail_block) { J->fail_block = b; J->fail_code = c.code; memcpy(J->fail_msg, c.msg, sizeof c.msg); }
            pthread_mutex_unlock(&J->mu);
            __atomic_store_n(&J->abort, 1, __ATOMIC_RELAXED);
        }
    }
    ail_par_cur = NULL;
}
/* The pool. Regions do not nest, so there is one job slot. A worker that sees the generation move
   tries to join the job (the state word holds the OPEN bit and the number of workers inside); the
   caller works, closes the job when no block is left, and waits only for workers that are inside.
   A worker that wakes late finds the job closed and goes back to waiting, so a region never waits
   for a thread the OS has not scheduled. Idle workers spin briefly before sleeping, so regions that
   follow each other closely cost no system call. */
#define AIL_PAR_OPEN ((int64_t)1 << 40)
AIL_LINK_STATE(ail_par_job, ail_par_slot, = {.mu = PTHREAD_MUTEX_INITIALIZER});
AIL_LINK_STATE(int64_t, ail_par_state, = 0);
AIL_LINK_STATE(pthread_mutex_t, ail_par_mu, = PTHREAD_MUTEX_INITIALIZER);
AIL_LINK_STATE(pthread_cond_t, ail_par_go, = PTHREAD_COND_INITIALIZER);
AIL_LINK_STATE(pthread_cond_t, ail_par_done, = PTHREAD_COND_INITIALIZER);
AIL_LINK_STATE(int64_t, ail_par_gen, = 0);
AIL_LINK_STATE(int, ail_par_pool, = 0);
AIL_LINK_STATE(int, ail_par_sleepers, = 0);
static void *ail_par_pool_main(void *start) {
    int64_t seen = (int64_t)(intptr_t)start;     /* the generation current when this worker was made */
    for (;;) {
        int64_t t0 = ail_par_now();
        for (unsigned k = 1; __atomic_load_n(&ail_par_gen, __ATOMIC_ACQUIRE) == seen; k++) {
            AIL_PAR_RELAX();
            if (!(k & 127) && ail_par_now() - t0 > AIL_PAR_SPIN_NS) break;
        }
        if (__atomic_load_n(&ail_par_gen, __ATOMIC_ACQUIRE) == seen) {
            pthread_mutex_lock(&ail_par_mu);
            while (__atomic_load_n(&ail_par_gen, __ATOMIC_ACQUIRE) == seen) {
                ail_par_sleepers++;
                pthread_cond_wait(&ail_par_go, &ail_par_mu);
                ail_par_sleepers--;
            }
            pthread_mutex_unlock(&ail_par_mu);
        }
        seen = __atomic_load_n(&ail_par_gen, __ATOMIC_ACQUIRE);
        int64_t s = __atomic_load_n(&ail_par_state, __ATOMIC_RELAXED);
        while ((s & AIL_PAR_OPEN) && !__atomic_compare_exchange_n(&ail_par_state, &s, s + 1, 0, __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {}
        if (!(s & AIL_PAR_OPEN)) continue;               /* the job was closed before this worker got here */
        ail_par_work(&ail_par_slot);
        if (__atomic_sub_fetch(&ail_par_state, 1, __ATOMIC_ACQ_REL) == 0) {
            pthread_mutex_lock(&ail_par_mu);
            pthread_cond_broadcast(&ail_par_done);
            pthread_mutex_unlock(&ail_par_mu);
        }
    }
    return NULL;
}
static void ail_par_go_wide(ail_par_fn fn, void **args, int64_t lo, int64_t hi) {
    int64_t n = hi - lo;
    int nt = ail_par_threads();
    if (nt > n) nt = (int)n;
    while (ail_par_pool < nt - 1) {
        pthread_t t;
        if (pthread_create(&t, NULL, ail_par_pool_main, (void *)(intptr_t)__atomic_load_n(&ail_par_gen, __ATOMIC_ACQUIRE))) break;
        pthread_detach(t);
        ail_par_pool++;
    }
    ail_par_job *J = &ail_par_slot;
    J->fn = fn; J->args = args; J->lo = lo; J->hi = hi;
    J->block = n / ((int64_t)(ail_par_pool < nt - 1 ? ail_par_pool + 1 : nt) * 8);
    if (J->block < 1) J->block = 1;
    J->nblocks = (n + J->block - 1) / J->block;
    J->next = 0; J->fail_block = INT64_MAX; J->abort = 0; J->fail_code = 0; J->fail_msg[0] = 0;
    if (ail_par_pool == 0) { ail_par_work(J); }
    else {
        __atomic_store_n(&ail_par_state, AIL_PAR_OPEN, __ATOMIC_RELEASE);
        __atomic_add_fetch(&ail_par_gen, 1, __ATOMIC_RELEASE);
        pthread_mutex_lock(&ail_par_mu);
        if (ail_par_sleepers) pthread_cond_broadcast(&ail_par_go);
        pthread_mutex_unlock(&ail_par_mu);
        ail_par_work(J);
        __atomic_and_fetch(&ail_par_state, ~AIL_PAR_OPEN, __ATOMIC_ACQ_REL);
        int64_t t0 = ail_par_now();
        for (unsigned k = 1; __atomic_load_n(&ail_par_state, __ATOMIC_ACQUIRE); k++) {
            AIL_PAR_RELAX();
            if (!(k & 127) && ail_par_now() - t0 > AIL_PAR_SPIN_NS) break;
        }
        if (__atomic_load_n(&ail_par_state, __ATOMIC_ACQUIRE)) {
            pthread_mutex_lock(&ail_par_mu);
            while (__atomic_load_n(&ail_par_state, __ATOMIC_ACQUIRE)) pthread_cond_wait(&ail_par_done, &ail_par_mu);
            pthread_mutex_unlock(&ail_par_mu);
        }
    }
    if (J->fail_block != INT64_MAX) {
        char msg[192];
        int code = J->fail_code;
        memcpy(msg, J->fail_msg, sizeof msg);
        if (msg[0]) ail_die(msg);
        ail_raise_named(code ? code : AIL_EXC_RUNTIME);
    }
}
static void ail_par_run(ail_par_fn fn, void **args, int64_t lo, int64_t hi, ail_par_site *S) {
    if (hi <= lo) return;
    int64_t n = hi - lo;
    if (lo < 0 || n < 0 || n < 2 || ail_par_threads() <= 1 || ail_par_cur) { fn(args, lo, hi); return; }
    int64_t i = lo;
    if (n > 64) {
        if (n <= S->light_n) {
            int64_t t0 = ail_par_now();
            fn(args, lo, hi);
            if (ail_par_now() - t0 > 2 * AIL_PAR_MIN_NS) S->light_n = n - 1;
            return;
        }
        if (!S->heavy_n || n < S->heavy_n) {
            int64_t t0 = ail_par_now(), step = 1;
            for (;;) {
                int64_t e = i + step;
                if (e > hi || e < i) e = hi;
                fn(args, i, e);
                i = e;
                if (i >= hi) { S->light_n = n; return; }
                int64_t spent = ail_par_now() - t0;
                if (spent >= AIL_PAR_PROBE_NS && (double)spent / (double)(i - lo) * (double)(hi - i) >= (double)AIL_PAR_MIN_NS) break;
                step *= 2;
            }
            S->heavy_n = n;
        }
    }
    if (hi - i < 2) { fn(args, i, hi); return; }
    ail_par_go_wide(fn, args, i, hi);
}
"""
ORDER.insert(ORDER.index('DIE') + 1, 'PAR')
SOURCE['PAR'] = PAR
REQUIRES['PAR'] = ['MONOTONICHEAD', 'TYPES', 'DIE']


# Typed parallel map and scoped threads (typedpar.py, docs/design/TYPED_PARALLEL.md):
# `ThreadPoolExecutor(max_workers=k).map`, `Pool(k).map` and k joined Threads run on the same pool with
# at most k threads, the calling thread included. Only a program with such a region carries PARN; it
# patches a copy of PAR (the worker count and the join test), so a program with `parallel for` alone
# keeps PAR byte for byte.
_PAR_CAPPED_EDITS = (
    ('static int ail_par_threads(void) {\n',
     'AIL_LINK_STATE(int, ail_par_cap, = 0);\n'
     'static int ail_par_threads_capped(void);\n'
     'static int ail_par_threads(void) {\n'),
    ('#define AIL_PAR_OPEN ((int64_t)1 << 40)\n',
     '#define AIL_PAR_OPEN ((int64_t)1 << 40)\n'
     'AIL_LINK_STATE(int64_t, ail_par_cap_inside, = 255);   /* pool workers that may join the open job */\n'),
    ('        while ((s & AIL_PAR_OPEN) && !__atomic_compare_exchange_n(&ail_par_state, &s, s + 1, 0, __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {}\n'
     '        if (!(s & AIL_PAR_OPEN)) continue;               /* the job was closed before this worker got here */\n',
     '        int64_t room = __atomic_load_n(&ail_par_cap_inside, __ATOMIC_RELAXED);\n'
     '        while ((s & AIL_PAR_OPEN) && (s & (AIL_PAR_OPEN - 1)) < room\n'
     '               && !__atomic_compare_exchange_n(&ail_par_state, &s, s + 1, 0, __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {}\n'
     '        if (!(s & AIL_PAR_OPEN) || (s & (AIL_PAR_OPEN - 1)) >= room) continue;   /* closed, or full */\n'),
    ('    int nt = ail_par_threads();\n', '    int nt = ail_par_threads_capped();\n'),
    ('    if (lo < 0 || n < 0 || n < 2 || ail_par_threads() <= 1 || ail_par_cur) { fn(args, lo, hi); return; }\n',
     '    if (lo < 0 || n < 0 || n < 2 || ail_par_threads_capped() <= 1 || ail_par_cur) { fn(args, lo, hi); return; }\n'),
)


def _par_capped(text):
    for old, new in _PAR_CAPPED_EDITS:
        if text.count(old) != 1:
            raise AssertionError('PARN: the PAR text changed; update _PAR_CAPPED_EDITS (%r)' % old[:60])
        text = text.replace(old, new)
    return text


PARN = r"""
static int ail_par_threads_capped(void) {
    int n = ail_par_threads();
    return ail_par_cap > 0 && ail_par_cap < n ? ail_par_cap : n;
}
/* One region on at most `cap` threads (cap <= 0: the default count). The calling thread is one of them,
   so at most cap - 1 pool workers may join. Regions do not nest and only the thread that runs one writes
   these words, before the job opens (the release that opens it publishes them). */
static void ail_par_run_n(ail_par_fn fn, void **args, int64_t lo, int64_t hi, ail_par_site *S, int64_t cap) {
    int keep = ail_par_cap;
    ail_par_cap = cap <= 0 ? 0 : cap > 256 ? 256 : (int)cap;
    __atomic_store_n(&ail_par_cap_inside, (int64_t)ail_par_threads_capped() - 1, __ATOMIC_RELAXED);
    ail_par_run(fn, args, lo, hi, S);
    ail_par_cap = keep;
    __atomic_store_n(&ail_par_cap_inside, 255, __ATOMIC_RELAXED);
}
"""
ORDER.insert(ORDER.index('PAR') + 1, 'PARN')
SOURCE['PARN'] = PARN
REQUIRES['PARN'] = ['PAR']


